mapper.select:
SELECT u.*, d.dept_name AS dept_name, (SELECT GROUP_CONCAT(r.role_name SEPARATOR ',') FROM sys_user_role ur INNER JOIN sys_role r ON r.id = ur.role_id WHERE ur.user_id = u.id) AS role_names FROM sys_user u LEFT JOIN sys_dept d ON d.id = u.dept_id WHERE u.del_flag = '0'
AND (u.user_name LIKE CONCAT('%', #{userName}, '%') OR u.nick_name LIKE CONCAT('%', #{userName}, '%'))
AND u.status = #{status}
AND (${dataScope})
ORDER BY u.id
LIMIT #{offset}, #{limit}

mapper.update:
UPDATE sys_user
SET password = #{password}
WHERE id = #{id}

UPDATE sys_user
SET login_ip = #{loginIp},
    login_date = #{loginDate}
WHERE id = #{id}
